import React from 'react';
import { GoogleMap, useJsApiLoader, Marker } from '@react-google-maps/api';

const containerStyle = { width: '100%', height: '100%' };
const defaultCenter = { lat: -6.208326360287679, lng: 106.79637092720068 };
const STORE_ICON = 'https://maps.google.com/mapfiles/ms/icons/green-dot.png';

const toPos = (e) => ({ lat: e.latLng.lat(), lng: e.latLng.lng() });

// Pemuat Google Maps bersama (satu kali untuk seluruh aplikasi). Dipakai komponen peta dan halaman checkout.
export function useGoogleMaps() {
  return useJsApiLoader({
    id: 'google-map-script',
    googleMapsApiKey: process.env.REACT_APP_GOOGLE_MAPS_API_KEY || 'YOUR_API_KEY_HERE',
    language: 'id',
    region: 'ID',
  });
}

/**
 * Peta serbaguna.
 * - center, zoom, markers: tampilan peta biasa (dipakai halaman Kontak)
 * - store: posisi toko (penanda hijau)
 * - pin + onPinChange: titik pengantaran yang bisa digeser
 * - onMapClick: dipanggil saat peta diketuk/diklik (menaruh pin)
 * - onUnavailable: dipanggil bila peta gagal dimuat (kunci/penagihan Google bermasalah)
 */
function GoogleMapComponent({ center, zoom = 14, markers = [], store = null, pin = null, onPinChange, onMapClick, onUnavailable }) {
  const { isLoaded, loadError } = useGoogleMaps();
  const [authFailed, setAuthFailed] = React.useState(false);

  // Titik awal hanya dibaca sekali supaya peta tidak "melompat" saat halaman dirender ulang.
  const [initialCenter] = React.useState(center || store || defaultCenter);
  const mapRef = React.useRef(null);
  // true bila pin baru dipindah pengguna di peta: peta tidak boleh zoom ulang sendiri,
  // supaya pengguna bisa memperbesar lalu menaruh pin dengan teliti.
  const userMovedRef = React.useRef(false);
  const interactive = !!(onMapClick || onPinChange);

  // Google memanggil fungsi global ini bila kunci API ditolak (billing/pembatasan domain)
  React.useEffect(() => {
    window.gm_authFailure = () => setAuthFailed(true);
    return () => { delete window.gm_authFailure; };
  }, []);

  const broken = !!loadError || authFailed;
  React.useEffect(() => { if (broken && onUnavailable) onUnavailable(); }, [broken]);

  const onLoad = React.useCallback((map) => { mapRef.current = map; }, []);
  const onUnmount = React.useCallback(() => { mapRef.current = null; }, []);

  const handleClick = React.useCallback((e) => {
    if (!onMapClick || !e.latLng) return;
    userMovedRef.current = true;
    onMapClick(toPos(e));
  }, [onMapClick]);

  const handleDragEnd = React.useCallback((e) => {
    if (!onPinChange || !e.latLng) return;
    userMovedRef.current = true;
    onPinChange(toPos(e));
  }, [onPinChange]);

  // Pin berubah karena pencarian / deteksi lokasi: tampilkan toko & pin sekaligus.
  React.useEffect(() => {
    const map = mapRef.current;
    if (!isLoaded || !map || !pin || !window.google) return;
    if (userMovedRef.current) { userMovedRef.current = false; return; }
    if (store) {
      const b = new window.google.maps.LatLngBounds();
      b.extend(store); b.extend(pin);
      map.fitBounds(b, 60);
    } else {
      map.panTo(pin);
    }
  }, [isLoaded, pin, store]);

  // Peta untuk memilih lokasi memakai gestureHandling "greedy": satu jari langsung menggeser peta
  // dan mengetuk menaruh pin (bukan menggulir halaman, bukan minta dua jari).
  const options = React.useMemo(() => ({
    maxZoom: 19,
    gestureHandling: interactive ? 'greedy' : 'auto',
    clickableIcons: false,           // ketukan pada ikon tempat tidak membuka kartu info yang menelan ketukan
    disableDoubleClickZoom: interactive,
    streetViewControl: false,
    mapTypeControl: false,
    fullscreenControl: interactive,  // layar penuh memudahkan menandai lokasi dari HP
    zoomControl: true,
    draggableCursor: interactive ? 'crosshair' : undefined,
  }), [interactive]);

  if (broken) {
    return (
      <div className="w-full h-full bg-slate-100 flex items-center justify-center text-sm text-slate-500 px-4 text-center">
        Peta tidak dapat dimuat saat ini. Gunakan opsi alamat manual.
      </div>
    );
  }
  if (!isLoaded) {
    return <div className="w-full h-full bg-gray-100 flex items-center justify-center text-gray-500">Memuat Peta...</div>;
  }

  return (
    <div className="relative w-full h-full">
      <GoogleMap
        mapContainerStyle={containerStyle}
        center={initialCenter}
        zoom={zoom}
        onLoad={onLoad}
        onUnmount={onUnmount}
        onClick={onMapClick ? handleClick : undefined}
        options={options}
      >
        {markers.map((pos, index) => (
          <Marker key={index} position={pos} />
        ))}
        {store && <Marker position={store} icon={STORE_ICON} title="Lokasi toko" clickable={false} />}
        {pin && (
          <Marker
            position={pin}
            title="Titik pengantaran"
            draggable={!!onPinChange}
            onDragEnd={onPinChange ? handleDragEnd : undefined}
          />
        )}
      </GoogleMap>
      {onMapClick && !pin && (
        <div className="pointer-events-none absolute left-1/2 top-3 -translate-x-1/2 whitespace-nowrap rounded-full bg-slate-900/80 px-3 py-1.5 text-xs font-semibold text-white shadow">
          Ketuk peta untuk menaruh pin
        </div>
      )}
    </div>
  );
}

export default React.memo(GoogleMapComponent);

/* ---------- pencarian & nama alamat (Google Geocoding) ---------- */

const geocoderReady = () => !!(window.google && window.google.maps && window.google.maps.Geocoder);

// Cari koordinat dari teks (alamat / nama tempat). `near` memprioritaskan hasil di sekitar toko.
export function geocodeAddress(address, near) {
  return new Promise((resolve, reject) => {
    if (!geocoderReady()) { reject(new Error('Peta belum siap. Tunggu sebentar lalu coba lagi.')); return; }
    const req = { address, region: 'id', componentRestrictions: { country: 'ID' } };
    if (near) {
      const d = 0.4;
      req.bounds = { south: near.lat - d, north: near.lat + d, west: near.lng - d, east: near.lng + d };
    }
    new window.google.maps.Geocoder().geocode(req, (results, status) => {
      if (status === 'OK' && results && results[0]) {
        const loc = results[0].geometry.location;
        resolve({ lat: loc.lat(), lng: loc.lng(), label: results[0].formatted_address });
      } else if (status === 'ZERO_RESULTS') {
        reject(new Error('Alamat tidak ditemukan. Tambahkan nama jalan, kelurahan, atau kota, atau ketuk langsung di peta.'));
      } else if (status === 'REQUEST_DENIED') {
        reject(new Error('Pencarian alamat belum aktif (Geocoding API belum diaktifkan untuk kunci peta). Ketuk langsung di peta.'));
      } else {
        reject(new Error('Pencarian alamat gagal. Coba lagi, atau ketuk langsung di peta.'));
      }
    });
  });
}

// Cari nama alamat dari koordinat. Tidak pernah melempar error: { label, status }.
export function reverseGeocode(pos) {
  return new Promise((resolve) => {
    if (!geocoderReady()) { resolve({ label: null, status: 'NOT_READY' }); return; }
    new window.google.maps.Geocoder().geocode({ location: pos, region: 'id' }, (results, status) => {
      if (status !== 'OK' || !results || !results.length) { resolve({ label: null, status }); return; }
      // Hindari hasil berupa kode plus ("7R2V+XX"), pilih alamat jalan bila ada
      const good = results.find((r) => !(r.types || []).includes('plus_code')) || results[0];
      const label = String(good.formatted_address || '').replace(/^[A-Z0-9]{4,8}\+[A-Z0-9]{2,3}\s*,?\s*/, '').trim();
      resolve({ label: label || null, status });
    });
  });
}
